def new_side(hunk_lines, start):
    # start: the number after '+' in the hunk header
    out = []
    n = start
    for line in hunk_lines:
        if line.startswith("+") or line.startswith(" "):
            out.append((n, line[1:]))
        n += 1
    return out

fn clip(text: &str, max: usize) -> &str {
    let head = &text[..max];
    match head.rfind('\n') {
        Some(n) if n > 0 => &head[..=n],
        _ => head,
    }
}

fn main() {
    let out = clip("\nabcdef", 5);
    println!("{:?}", out);
}

